"use strict";

const { AsyncLocalStorage } = require("async_hooks");
const { performance } = require("perf_hooks");

exports.summarize = async function summarize(labels) {
  const storage = new AsyncLocalStorage();
  const startedAt = performance.now();
  const seen = [];

  await storage.run({ label: labels[0] }, async () => {
    seen.push(storage.getStore().label);
    await Promise.resolve();
    await storage.run({ label: labels[1] }, async () => {
      seen.push(storage.getStore().label);
    });
    seen.push(storage.getStore().label);
  });

  return `asyncperf:${seen.join(">")}:${performance.now() >= startedAt}`;
};
